// Copyright 2015-2021 Crytek GmbH / Crytek Group. All rights reserved.#pragma once#include "Common/GraphicsPipelineStage.h"#include "Common/FullscreenPass.h"#include "Common/PrimitiveRenderPass.h"#include "Common/UtilityPasses.h"struct SHDRStreaksParams;class CBloomStage : public CGraphicsPipelineStage{public:	static const EGraphicsPipelineStage StageID = eStage_Bloom;	//! Ray count ceiling for the diffraction streaks, mirrored by CHDRStreaks::s_nMaxDirections.	static const int kMaxStreakDirections = 12; //!< Line passes; each paints two opposed spikes (24 max).	//! Stretch iterations per ray. Each one widens the tap stride by the tap count, so two	//! iterations of 8 taps already reach 63 tap distances from the source.	static const int kStreakIterations = 2;	//! Stretch iterations for the anamorphic horizontal flare. One more than the blade streaks:	//! 8^3 tap distances span the whole frame width, which is what makes the line read as a	//! single stroke across the frame instead of a stubby spike.	static const int kAnamorphicIterations = 3;	//! Gaussian iterations for the halation halo, run at 1/16 resolution. CGaussianBlurPass has	//! a fixed 16 tap footprint (+-8 texels) whatever its distribution, so the halo's WIDTH comes	//! from the resolution it runs at (+-8 texels at 1/16 = +-128 full-res pixels), and being a	//! true separable Gaussian it is isotropic - a round halo, as emulsion scatter is.	static const int kHalationBlurIterations = 2;	CBloomStage(CGraphicsPipeline& graphicsPipeline)		: CGraphicsPipelineStage(graphicsPipeline)		, m_pass1H(&graphicsPipeline)		, m_pass1V(&graphicsPipeline)		, m_pass2H(&graphicsPipeline)		, m_pass2V(&graphicsPipeline)		, m_passStreakThreshold(&graphicsPipeline)		, m_passAnamorphicThreshold(&graphicsPipeline)		, m_passFilterThreshold(&graphicsPipeline)		, m_passDiffractionThreshold(&graphicsPipeline)		, m_passDiffractionBlurH(&graphicsPipeline)		, m_passDiffractionBlurV(&graphicsPipeline)		, m_passDiffractionDebug(&graphicsPipeline)		, m_passDiffractionComposite(&graphicsPipeline)		, m_passDiffractionReadbackCopy(&graphicsPipeline)		, m_passHalationThreshold(&graphicsPipeline)		, m_passHalationDown0(&graphicsPipeline)		, m_passHalationDown1(&graphicsPipeline)		, m_passHalationBlur(&graphicsPipeline)		, m_passHalationComposite(&graphicsPipeline)	{		for (int direction = 0; direction < kMaxStreakDirections; ++direction)		{			for (int iteration = 0; iteration < kStreakIterations; ++iteration)				m_passStreakStretch[direction][iteration].SetGraphicsPipeline(&graphicsPipeline);		}		for (int iteration = 0; iteration < kAnamorphicIterations; ++iteration)			m_passAnamorphicStretch[iteration].SetGraphicsPipeline(&graphicsPipeline);	}	bool IsStageActive(EShaderRenderingFlags flags) const final	{		return CRenderer::CV_r_HDRBloom && CRenderer::CV_r_PostProcess;	}	void Execute();	//! Adds the wave-glare layer into the HDR target. Called by the pipeline right after	//! Execute(), in the same window as the DOF's ghost composite: the glare has its own	//! half-resolution layer now instead of travelling through $HDRFinalBloom, so it needs its	//! own composite. Consume-once, and a no-op in every frame the glare pass did not run.	void ExecuteDiffractionComposite();private:	void ExecuteStreaks();	void ExecuteDiffraction(const SHDRStreaksParams& streakParams, float fBloomCompositeWeight);	void UpdateDiffractionSourceReadback(int nDebugMode, CTexture* pSource, float fThreshold);	void ExecuteFilterPSF();	void ExecuteHalation();	CFullscreenPass m_pass1H;	CFullscreenPass m_pass1V;	CFullscreenPass m_pass2H;	CFullscreenPass m_pass2V;	CFullscreenPass m_passStreakThreshold;	CFullscreenPass m_passStreakStretch[kMaxStreakDirections][kStreakIterations];	CFullscreenPass m_passAnamorphicThreshold;	CFullscreenPass m_passAnamorphicStretch[kAnamorphicIterations];	// Front filter PSF: a threshold pass into the shared scratch target, then one sprite draw	// per bright quarter-resolution texel. The sprites are procedural geometry expanded from	// SV_VertexID, so the pass needs a primitive pass and a per-view constant buffer of its	// own describing the quarter-resolution GRID (the DOF's splat and ghost passes do the	// same for their grids).	CFullscreenPass      m_passFilterThreshold;	CPrimitiveRenderPass m_passFilterPSF;	CRenderPrimitive     m_filterPSFPrimitive;	CConstantBufferPtr   m_pFilterPSFPerViewCB;	// Wave-optics diffraction glare (DiffractionKernelSpec.md). Same sparse convolution shape as	// the front filter above - a threshold pass and one sprite per surviving source texel - but	// the pattern is not authored: it is the FFT of the pupil, built by the DOF stage's job,	// sampled radially and extrapolated past its own edge by the edge-diffraction law. The debug	// pass draws that kernel into the corner of the frame.	//	// Everything here runs at HALF resolution and into a layer of its own, unlike the rest of the	// glare family. At quarter resolution a lamp is a 3x3 block of thresholded texels, each of	// which spawns a sprite, so the SUM of those sprites has the block's square as its centre;	// and the deposit was then bilinearly magnified 4x onto the pattern's steepest slope, which	// is what put visible square blocks around every source. Half resolution halves both errors	// in each axis, and the source pre-blur below turns the block into a round blob.	CFullscreenPass      m_passDiffractionThreshold;	CFullscreenPass      m_passDiffractionBlurH;	CFullscreenPass      m_passDiffractionBlurV;	CPrimitiveRenderPass m_passDiffraction;	CRenderPrimitive     m_diffractionPrimitive;	CConstantBufferPtr   m_pDiffractionPerViewCB;	CFullscreenPass      m_passDiffractionDebug;	CFullscreenPass      m_passDiffractionComposite;	// Half-resolution glare targets: the thresholded (and pre-blurred) source, its separable	// blur scratch, and the RGBA16F layer the sprites deposit into. Allocated lazily like the	// halation targets, so Analytic mode and glare off cost nothing.	_smart_ptr<CTexture> m_pTexDiffractionSource;	_smart_ptr<CTexture> m_pTexDiffractionSourceTemp;	_smart_ptr<CTexture> m_pTexDiffractionLayer;	int                  m_diffractionLayerWidth = 0;	int                  m_diffractionLayerHeight = 0;	bool                 m_bDiffractionLayerValid = false;	bool AcquireDiffractionTargets(int halfWidth, int halfHeight);	void ReleaseDiffractionTargets();	// r_HDRDiffractionDebug 3 also reports the brightest source on screen in the log. The	// thresholded source is a GPU texture, so the number has to come back over a staging copy:	// blit the quarter-resolution excess into a readback target once a second, issue the	// download, and map it a few frames later when the fence has signalled. Nothing here stalls	// the pipeline, and none of it is allocated unless the mode is on.	CStretchRectPass     m_passDiffractionReadbackCopy;	_smart_ptr<CTexture> m_pTexDiffractionReadback;	bool                 m_bDiffractionReadbackIssued = false;	bool                 m_bDiffractionReadbackStalled = false;	float                m_fDiffractionReadbackTime = 0.0f;	CFullscreenPass   m_passHalationThreshold;	CStretchRectPass  m_passHalationDown0;   // quarter -> 1/8	CStretchRectPass  m_passHalationDown1;   // 1/8 -> 1/16	CGaussianBlurPass m_passHalationBlur;	CFullscreenPass   m_passHalationComposite;	// Low-resolution halation targets (the shared HDR chain stops at quarter resolution).	// Allocated lazily, so halation off costs nothing.	_smart_ptr<CTexture> m_pTexHalationEighth;	_smart_ptr<CTexture> m_pTexHalationLow;	_smart_ptr<CTexture> m_pTexHalationLowTemp;	int                  m_halationLowWidth = 0;	int                  m_halationLowHeight = 0;	bool AcquireHalationTargets(int quarterWidth, int quarterHeight);	void ReleaseHalationTargets();};